queries:
SELECT SUM(rebtotal), AVG(feerate - rebrate) FROM fees WHERE rebrate > 0.0005;
SELECT AVG(feerate) - AVG(rebrate) FROM fees;
SELECT AVG(feerate - rebrate) FROM fees WHERE feerate IS NOT NULL AND rebrate IS NOT NULL
SELECT SUM(rebtotal) AS total_rebate, AVG(CASE WHEN feerate IS NOT NULL THEN feerate - rebrate END) AS avg_net_rate FROM fees
SELECT SUM(rebtotal) AS total_rebtotal, AVG(feerate) AS avg_feerate
FROM fees
WHERE feerate IS NOT NULL;
